package studio.jiayu.neoagent;
import android.app.KeyguardManager;import android.content.*;import android.graphics.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.view.accessibility.*;import android.view.inputmethod.InputMethodManager;import android.widget.EditText;import org.json.*;import java.util.*;
/** User-invoked shortcut to the current IME. No microphone permission or audio upload. */
final class FloatingVoiceInput {
 private final ControlService host;private final Handler main=new Handler(Looper.getMainLooper());private final TouchPointPicker points=new TouchPointPicker();
 private long epoch;private boolean dispatched;private String status="由当前输入法处理语音";private EditText editor;private int attempts,candidates;
 FloatingVoiceInput(ControlService host){this.host=host;}
 String status(){return status;}
 JSONObject snapshot(){JSONObject o=new JSONObject();try{o.put("status",status).put("attempts",attempts).put("candidates",candidates).put("dispatch_attempted",dispatched).put("microphone_owned_by_agent",false);}catch(Exception ignored){}return o;}
 void start(EditText input){cancel();if(input==null||!host.ownsConnection()||host.running)return;editor=input;input.requestFocus();final long request=epoch;attempts=0;candidates=0;dispatched=false;setStatus("正在打开当前输入法…");input.post(()->prepare(request,0));}
 private void prepare(long request,int tries){if(request!=epoch||editor==null||!editor.isAttachedToWindow()||!host.ownsConnection()||host.running)return;editor.requestFocus();if(!editor.hasWindowFocus()||!editor.hasFocus()){if(tries<12)main.postDelayed(()->prepare(request,tries+1),100);else setStatus("对话面板暂未取得输入焦点，请再次点语音");return;}if(!current(request))return;((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(editor,0);main.postDelayed(()->attempt(request),350);}
 private boolean current(long request){boolean unlocked=!((KeyguardManager)host.getSystemService(Context.KEYGUARD_SERVICE)).isKeyguardLocked();return request==epoch&&editor!=null&&VoiceShortcutRules.allowed(host.ownsConnection(),host.running,editor.isAttachedToWindow(),editor.hasFocus()&&editor.hasWindowFocus(),unlocked);}
 private String imePackage(){try{ComponentName c=ComponentName.unflattenFromString(Settings.Secure.getString(host.getContentResolver(),Settings.Secure.DEFAULT_INPUT_METHOD));return c==null?"":c.getPackageName();}catch(RuntimeException failed){return "";}}
 private static final class Candidate {final AccessibilityNodeInfo node;final int window;final String identity,pkg;final Rect box;Candidate(AccessibilityNodeInfo n,int w,String pkg){node=n;window=w;this.pkg=pkg;identity=GuiRevision.identity(n);box=new Rect();n.getBoundsInScreen(box);}}
 private List<Candidate> find(String pkg){LinkedHashMap<String,Candidate> result=new LinkedHashMap<>();if(pkg.isEmpty())return new ArrayList<>();int count=0;
  for(AccessibilityWindowInfo w:host.getWindows()){if(w.getType()!=AccessibilityWindowInfo.TYPE_INPUT_METHOD)continue;AccessibilityNodeInfo root=w.getRoot();if(root==null||!pkg.contentEquals(root.getPackageName()))continue;Rect frame=new Rect();w.getBoundsInScreen(frame);ArrayDeque<AccessibilityNodeInfo> q=new ArrayDeque<>();q.add(root);
   while(!q.isEmpty()&&count++<600){AccessibilityNodeInfo n=q.remove();if(n.isVisibleToUser()&&n.isEnabled()&&(VoiceShortcutRules.activationLabel(n.getContentDescription())||VoiceShortcutRules.activationLabel(n.getText()))){AccessibilityNodeInfo action=n;for(int depth=0;action!=null&&!action.isClickable()&&depth<4;depth++)action=action.getParent();if(action!=null&&action.isClickable()&&(action.getActions()&AccessibilityNodeInfo.ACTION_CLICK)!=0&&action.isVisibleToUser()&&action.isEnabled()&&pkg.contentEquals(action.getPackageName())&&action.getWindowId()==w.getId()){Candidate c=new Candidate(action,w.getId(),pkg);if(c.box.width()>8&&c.box.height()>8&&frame.contains(c.box))result.put(c.identity,c);}}
    for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null)q.add(child);}
   }
  }return new ArrayList<>(result.values());
 }
 private boolean unobscured(Candidate c,int x,int y){int layer=Integer.MIN_VALUE;List<AccessibilityWindowInfo> windows=host.getWindows();for(AccessibilityWindowInfo w:windows)if(w.getId()==c.window&&w.getType()==AccessibilityWindowInfo.TYPE_INPUT_METHOD){layer=w.getLayer();break;}if(layer==Integer.MIN_VALUE)return false;for(AccessibilityWindowInfo w:windows){if(w.getId()==c.window||w.getLayer()<=layer)continue;String title=w.getTitle()==null?"":w.getTitle().toString();if(w.getType()==AccessibilityWindowInfo.TYPE_ACCESSIBILITY_OVERLAY&&!host.effectsWindowTitle.isEmpty()&&title.equals(host.effectsWindowTitle))continue;Rect b=new Rect();w.getBoundsInScreen(b);if(b.contains(x,y))return false;}return true;}
 private void attempt(long request){if(!current(request)||dispatched)return;attempts++;String pkg=imePackage();List<Candidate> found=find(pkg);candidates=found.size();if(!VoiceShortcutRules.unique(candidates)){if(attempts<3){main.postDelayed(()->attempt(request),450);return;}setStatus("已打开当前键盘，点键盘麦克风开始说话");return;}Candidate c=found.get(0);
  try{if(!current(request)||!pkg.equals(imePackage())||!c.node.refresh()||!c.identity.equals(GuiRevision.identity(c.node)))return;List<Candidate> fresh=find(pkg);if(fresh.size()!=1||fresh.get(0).window!=c.window||!fresh.get(0).identity.equals(c.identity))return;Rect b=c.box;int margin=Math.max(1,host.dp(3));Rect inner=new Rect(b);inner.inset(Math.min(margin,(b.width()-2)/2),Math.min(margin,(b.height()-2)/2));int[] p=points.pick(inner.left,inner.top,inner.right,inner.bottom,inner.centerX(),inner.centerY(),Math.max(2,host.dp(4)));if(!current(request))return;if(!unobscured(c,p[0],p[1])){setStatus("语音入口被遮挡，请在键盘上点麦克风");return;}Path path=new Path();path.moveTo(p[0],p[1]);dispatched=true;boolean accepted=host.dispatchGesture(new android.accessibilityservice.GestureDescription.Builder().addStroke(new android.accessibilityservice.GestureDescription.StrokeDescription(path,0,70)).build(),new android.accessibilityservice.AccessibilityService.GestureResultCallback(){@Override public void onCompleted(android.accessibilityservice.GestureDescription g){if(request==epoch&&editor!=null&&editor.isAttachedToWindow())setStatus("语音入口已点按，请核对转写后发送");}@Override public void onCancelled(android.accessibilityservice.GestureDescription g){if(request==epoch&&editor!=null&&editor.isAttachedToWindow())setStatus("点键盘麦克风开始说话");}},main);if(!accepted)setStatus("点键盘麦克风开始说话");else setStatus("已请求键盘语音入口，核对转写后发送");
  }catch(RuntimeException rejected){setStatus("已打开键盘，点其麦克风开始说话");}
 }
 private void setStatus(String text){status=text;if(host.floatingChat!=null)host.floatingChat.voiceStatus(text);}
 void cancel(){epoch++;main.removeCallbacksAndMessages(null);editor=null;dispatched=false;}
 void close(){cancel();}
}
